fun {α} [BEq α] [Hashable α] {ρ} [ForIn Id ρ α] xs s =>
  (have result := s;
    do
    let __s ←
      forIn xs result fun x __s =>
          have result := __s;
          have result := Aesop.OrderedHashSet.insert x result;
          pure (ForInStep.yield result)
    have result : Aesop.OrderedHashSet α := __s
    pure result).run

